"""Standalone read-only production workbench, independent from Chat state."""

BOARD_HTML = '''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>数据生产线路</title><link rel="stylesheet" href="/production.css"></head><body><a class="skip" href="#main">跳到线路总览</a><header><a class="brand" href="/">DSH Retrieval</a><nav><a aria-current="page" href="/">生产线路</a><a href="/chat">新建需求 / 历史 Chat</a><a href="/catalog">已有索引配置</a></nav></header><main id="main"><div class="heading"><div><small>PRODUCTION WORKSPACE</small><h1>数据生产线路</h1><p>查看交付目标、有效数量和需要处理的事项；进入详情查看各阶段产物。</p></div><a class="primary" href="/chat">＋ 新建需求</a></div><div id="overview-summary" class="overview-summary" aria-label="需求概览"></div><section class="panel"><div class="toolbar"><h2>线路总览</h2><label for="line-search">搜索</label><input id="line-search" type="search" placeholder="需求内容或任务 ID"><label for="line-filter">状态</label><select id="line-filter"><option value="">全部状态</option><option value="RUNNING">运行中</option><option value="AWAITING_INPUT">待操作</option><option value="COMPLETED">已完成</option><option value="FAILED">失败</option><option value="PAUSED">已暂停</option><option value="PARTIAL">部分完成</option><option value="CREATED">已创建</option><option value="PLANNING">规划中</option><option value="PARSING">需求解析中</option><option value="CANCELLED">已取消</option></select><button id="line-refresh" type="button">刷新</button></div><p id="line-status" role="status" aria-live="polite">正在读取线路清单…</p><div class="table-wrap"><table><thead><tr><th>需求</th><th>运行状态</th><th>生产过程</th><th>交付目标与缺口</th><th>创建时间</th><th>下一步</th></tr></thead><tbody id="line-rows"></tbody></table></div></section><section id="line-detail" class="panel detail hidden" aria-labelledby="detail-title"><div class="detail-head"><div><small>LINE DETAIL</small><h2 id="detail-title">线路详情</h2><p id="detail-id"></p></div><button id="detail-close" type="button">关闭详情</button></div><p id="detail-status" role="status"></p><div id="detail-body"></div></section></main><script src="/production.js"></script></body></html>'''

BOARD_CSS = '''
:root{font-family:Inter,"PingFang SC",system-ui,sans-serif;color:#202421;background:#f7f7f5;--line:#dedfdb;--muted:#69736b}*{box-sizing:border-box}body{margin:0}.skip{position:absolute;top:-100px}.skip:focus{top:4px}header{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:16px max(24px,calc((100vw - 1450px)/2));background:white;border-bottom:1px solid var(--line)}.brand{font-weight:800;color:#202421;text-decoration:none}nav{display:flex;gap:8px;flex-wrap:wrap}nav a{color:#3c5142;text-decoration:none;font-size:13px;padding:8px 12px;border-radius:8px}nav a[aria-current]{background:#e5f0e8;font-weight:700}main{max-width:1500px;margin:auto;padding:26px 24px 70px}.heading,.detail-head{display:flex;justify-content:space-between;align-items:center;gap:18px}.heading{margin-bottom:22px}.heading small,.detail-head small{font-size:11px;font-weight:800;letter-spacing:.14em;color:#5b8066}h1{font-size:29px;margin:4px 0}h2{font-size:18px;margin:0}.heading p,.detail-head p{color:var(--muted);font-size:13px;margin:5px 0}.primary{background:#246646;color:white;text-decoration:none;border-radius:9px;padding:10px 16px;white-space:nowrap;font-size:13px;font-weight:700}.panel{background:white;border:1px solid var(--line);border-radius:14px;box-shadow:0 10px 32px #1c2c2210}button,input,select{font:inherit}button{border:1px solid var(--line);border-radius:8px;background:white;padding:8px 12px;cursor:pointer;color:#2f4936}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid #246646;outline-offset:2px}.toolbar{display:flex;align-items:center;gap:10px;flex-wrap:wrap;padding:18px}.toolbar h2{margin-right:auto}.toolbar label{font-size:12px;font-weight:700}.toolbar input,.toolbar select{border:1px solid var(--line);border-radius:8px;padding:8px;background:white}.toolbar input{width:min(290px,100%)}#line-status{font-size:12px;color:var(--muted);margin:0;padding:0 18px 12px}.table-wrap{overflow:auto;max-height:calc(100vh - 290px);min-height:250px;border-top:1px solid var(--line)}table{border-collapse:collapse;width:100%;min-width:950px;font-size:12px}td,th{border-bottom:1px solid #e8ebe7;text-align:left;padding:11px 12px;vertical-align:middle}th{position:sticky;top:0;z-index:2;background:#f3f6f2;font-size:11px;color:#48534b}td:last-child,th:last-child{position:sticky;right:0;z-index:3;background:white;box-shadow:-8px 0 14px #17221c0d}td:last-child button{white-space:nowrap}th:last-child{z-index:4;background:#f3f6f2}tr:hover td,tr.selected td{background:#f8faf7}.name{display:block;max-width:340px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-size:13px;font-weight:700}.id{display:block;color:var(--muted);font-size:10px;margin-top:3px}.state{display:inline-block;padding:4px 8px;border-radius:999px;background:#edf1ed;white-space:nowrap;font-weight:700}.state[data-state=FAILED],.node[data-status=failed]{background:#fff0ee;color:#9f2525}.state[data-state=AWAITING_INPUT]{background:#fff5dd;color:#805c19}.nodes{display:flex;gap:4px;min-width:330px}.node{display:inline-flex;align-items:center;justify-content:center;min-width:55px;padding:5px 4px;border-radius:6px;background:#eff1ee;color:#737b75;font-size:10px;white-space:nowrap}.node[data-status=succeeded]{background:#e2f1e6;color:#246646}.node[data-status=running]{background:#dbe9fb;color:#235b9a}.count{white-space:nowrap}.hidden{display:none}.detail{margin-top:18px;padding:20px}.detail-head p{overflow-wrap:anywhere}#detail-status{font-size:12px;color:var(--muted)}.stats{display:flex;flex-wrap:wrap;gap:10px;margin:18px 0}.stat{background:#f5f7f4;border-radius:10px;padding:12px;min-width:125px}.stat b{display:block;font-size:17px}.stat span{font-size:11px;color:var(--muted)}.detail-nodes{display:grid;grid-template-columns:repeat(5,minmax(120px,1fr));gap:9px}.detail-node{border:1px solid var(--line);border-radius:10px;padding:12px;min-width:0}.detail-node strong{display:block;margin:8px 0 5px}.detail-node p{font-size:11px;color:var(--muted);margin:0;overflow-wrap:anywhere}@media(max-width:760px){header,.heading{flex-direction:column;align-items:start}header{padding:14px 16px}main{padding:18px 12px}.toolbar h2{width:100%}.toolbar input{flex:1}.detail-nodes{grid-template-columns:repeat(2,minmax(0,1fr))}.table-wrap{max-height:50vh}}
'''

BOARD_JS = r'''
const $=id=>document.getElementById(id),headers={'X-Tenant-Id':'tenant-a','X-User-Id':'user-a'};
const nodeNames={expansion:'扩词',retrieval:'检索',cleaning:'清洗',refill:'补数',packaging:'打包'};
const stateNames={CREATED:'已创建',PARSING:'需求解析中',PLANNING:'规划中',RUNNING:'运行中',AWAITING_INPUT:'待操作',PAUSED:'已暂停',PARTIAL:'部分完成',COMPLETED:'已完成',FAILED:'失败',CANCELLED:'已取消'};
let rows=[],rowEls=new Map(),listEpoch=0,detailEpoch=0,selected=new URLSearchParams(location.search).get('task');
async function api(path){const response=await fetch(path,{headers,cache:'no-store'}),data=await response.json();if(!response.ok)throw new Error(`${data.code||response.status}: ${data.message||'读取失败'}`);return data}
function cell(row,value){const el=document.createElement('td');if(value!==undefined)el.textContent=value;row.append(el);return el}
function date(value){if(!value)return'时间未知';const d=new Date(value);return Number.isNaN(d.getTime())?'时间未知':new Intl.DateTimeFormat('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(d)}
function visible(item){const q=$('line-search').value.trim().toLowerCase(),status=$('line-filter').value;return(!status||item.run_status===status)&&(!q||(item.title+' '+item.task_id).toLowerCase().includes(q))}
function updateRow(item){updateOverviewSummary();const row=rowEls.get(item.task_id);if(!row)return;for(const node of row.querySelectorAll('.node')){const detail=item.progress?.nodes?.find(n=>n.node===node.dataset.node);node.dataset.status=detail?.node_status||'pending';node.title=detail?`${detail.label}：${detail.detail}`:'状态暂不可读'}const counts=row.querySelector('.count');counts.replaceChildren();const goal=document.createElement('div');goal.className='goal-line';goal.textContent=goalSummary(item);counts.append(goal);const note=document.createElement('div');note.className='goal-note';note.textContent=item.error?'上次读取结果，可能滞后':`待复核 ${knownCount(item.progress?.counts.pending_review)} · 有效数不等于清洗通过数`;counts.append(note);const badge=row.querySelector('.state');badge.dataset.state=item.progress?.run_status||item.run_status;badge.textContent=runStatusLabel(item);const action=row.querySelector('.row-action');action.replaceChildren();renderNextAction(action,item)}
function render(){const body=$('line-rows');body.replaceChildren();rowEls=new Map();let shown=0;for(const item of rows){if(!visible(item))continue;shown++;const row=document.createElement('tr');row.classList.toggle('selected',item.task_id===selected);rowEls.set(item.task_id,row);const nameCell=cell(row),name=document.createElement('span'),id=document.createElement('span');name.className='name';name.textContent=item.title;name.title=item.title;id.className='id';id.textContent=item.task_id;nameCell.append(name,id);const stateCell=cell(row),badge=document.createElement('span');badge.className='state';badge.dataset.state=item.run_status;badge.textContent=runStatusLabel(item);stateCell.append(badge);const nodesCell=cell(row),strip=document.createElement('div');strip.className='nodes';for(const key of Object.keys(nodeNames)){const node=document.createElement('a');node.href=nodeURL(item.task_id,key);node.className='node';node.dataset.node=key;node.textContent=nodeNames[key];strip.append(node)}const process=document.createElement('details'),summary=document.createElement('summary');process.className='row-process';summary.textContent='查看五个生产节点';process.append(summary,strip);nodesCell.append(process);cell(row,'读取中').className='count';cell(row,date(item.created_at));const action=cell(row),button=document.createElement('a');button.href=nodeURL(item.task_id);button.textContent='查看详情';action.className='row-action';action.append(button);body.append(row);updateRow(item)}if(!shown){const row=document.createElement('tr'),empty=cell(row,rows.length?'没有符合条件的线路':'暂无已确认线路');empty.colSpan=6;body.append(row)}$('line-status').textContent=`共 ${rows.length} 条已确认线路 · 当前显示 ${shown} 条`}
function stat(box,label,value){const el=document.createElement('div'),number=document.createElement('b'),caption=document.createElement('span');el.className='stat';number.textContent=value??'未知';caption.textContent=label;el.append(number,caption);box.append(el)}
function showDetail(item){if(item.task_id!==selected)return;const progress=item.progress,body=$('detail-body');$('detail-title').textContent=item.title;$('detail-id').textContent=`任务 ${item.task_id} · ${runStatusLabel(item)} · 创建于 ${date(item.created_at)}`;body.replaceChildren();if(!progress){$('detail-status').textContent=item.error?'线路状态读取失败：'+item.error:'正在读取节点状态…';return}$('detail-status').textContent=`正式版本 ${progress.revision} · generation ${progress.run_generation} · ${progress.note||'以当前权威状态为准'}`;const stats=document.createElement('div');stats.className='stats';for(const [label,value] of [['目标',progress.counts.target],['有效素材',progress.counts.accepted],['当前缺口',progress.counts.gap],['规则待复核',progress.counts.pending_review],['原始返回',progress.counts.returned],['清洗通过',progress.counts.passed]])stat(stats,label,value);body.append(stats);const next=document.createElement('div');next.className='attention';renderNextAction(next,item);body.append(next);const nodes=document.createElement('div');nodes.className='detail-nodes';for(const node of progress.nodes){const box=document.createElement('a'),badge=document.createElement('span'),title=document.createElement('strong'),detail=document.createElement('p');box.className='detail-node';box.dataset.node=node.node;box.href=nodeURL(item.task_id,node.node);badge.className='node';badge.dataset.status=node.node_status;const stopped=node.node==='refill'&&node.detail.includes('自动补数已停止');badge.textContent=stopped?'已停止':(node.node_status==='running'&&progress.run_status==='PLANNING')?'规划中':(({succeeded:'已通过',running:'进行中',failed:'失败',cancelled:'已取消'})[node.node_status]||'待开始');title.textContent=node.label;detail.textContent=`${node.mode==='manual'?'人工确认':'自动推进'} · ${node.detail}`;box.append(badge,title,detail);nodes.append(box)}body.append(nodes);const note=document.createElement('p');note.textContent='数量未知不按零计算；SHA-256 完全一致自动去重；不显示整体完成百分比。';body.append(note)}
async function load(){const epoch=++listEpoch;$('line-status').textContent='正在读取线路清单…';try{const previous=new Map(rows.map(item=>[item.task_id,item]));const tasks=await api('/v1/retrieval/projects/demo/tasks');if(epoch!==listEpoch)return;rows=tasks.items.map(item=>({...item,title:item.raw_request||item.task_id,progress:previous.get(item.task_id)?.progress?.task_version===item.task_version?previous.get(item.task_id).progress:undefined})).sort((a,b)=>String(b.created_at).localeCompare(String(a.created_at)));render();if(selected&&rows.some(item=>item.task_id===selected))selectLine(selected);else if(selected){selected=null;$('line-detail').classList.add('hidden')}let cursor=0;async function worker(){while(cursor<rows.length&&epoch===listEpoch){const item=rows[cursor++];try{item.progress=await api(`/v1/retrieval/tasks/${encodeURIComponent(item.task_id)}/progress`);item.error=null}catch(error){item.error=error.message}if(epoch!==listEpoch)return;updateRow(item);if(item.task_id===selected)showDetail(item)}}await Promise.all([worker(),worker(),worker()])}catch(error){if(epoch!==listEpoch)return;$('line-status').textContent='线路清单读取失败：'+error.message;for(const item of rows)item.error='清单刷新失败，状态可能滞后';for(const item of rows)updateRow(item)}}
$('line-search').oninput=render;$('line-filter').onchange=render;$('line-refresh').onclick=load;$('detail-close').onclick=()=>{selected=null;detailEpoch++;$('line-detail').classList.add('hidden');history.replaceState(null,'','/production');render()};
'''

from .production_cleaning_ui import CLEANING_HTML, CLEANING_CSS, CLEANING_JS

BOARD_HTML = BOARD_HTML.replace('</main>', CLEANING_HTML + '</main>')
BOARD_HTML = BOARD_HTML.replace('<button id="detail-close"', '<a id="detail-chat" href="/chat">继续此 Chat</a><button id="detail-close"')
BOARD_CSS += CLEANING_CSS
BOARD_JS += CLEANING_JS

from .production_outputs_ui import OUTPUT_CSS, OUTPUT_JS

# Keep the overview and bookmarkable task output in separate navigations.
BOARD_CSS += OUTPUT_CSS
BOARD_JS += OUTPUT_JS

from .production_experience_ui import EXPERIENCE_HTML, EXPERIENCE_CSS, EXPERIENCE_JS

BOARD_HTML = BOARD_HTML.replace('</main>', EXPERIENCE_HTML + '</main>')
BOARD_CSS += EXPERIENCE_CSS
BOARD_JS += EXPERIENCE_JS + '\ninitializeAssetViewer();\nstartProduction();\n'
